    /** OAuth 获取 Token 时认证信息的请求位置：URL、Headers、Body */
    AuthPosition?: string;
    /** OAuth 授权模式匹配的参数字段名 */
    GrantType?: string;
    /** OAuth 授权模式类型，如 authorization_code、client_credentials */
    ClientCredentials?: string;
    /** OAuth 返回中 access_token 的映射字段名 */
    AccessToken?: string;
    /** OAuth 返回中 Token 有效期的映射字段名 */
    ExpiresIn?: string;
